class GlossaryResolver:
    """Type-scoped normalized lookup into one language pair's glossary.

    Index key is (term_type, normalized source). The DB enforces uniqueness
    on (source_lang, source, term_type), so first-row-wins on normalized
    collisions is only reachable through normalization merges — conservative
    enough to accept.
    """

    def __init__(self, glossary: MockGlossary) -> None:
        self._glossary = glossary
        self._index: dict[tuple[str, str], int] = {}
        for i, row in enumerate(glossary.terms):
            key = (row.term_type, normalize_term(row.source))
            self._index.setdefault(key, i)

    def resolve(
        self, *, source: str, term_type: GlossaryType
    ) -> GlossaryTranslatedTerm | None:
